<?php
require_once '_bootstrap.php';require_admin_permission('customers.view');$db=admin_db();
if($_SERVER['REQUEST_METHOD']==='POST'){
    verify_csrf();$email=trim($_POST['email']??'');$action=$_POST['action']??'';
    if($action==='access'){if(!admin_can('customers.manage'))redirect_with_message('customers.php','You do not have permission to change customer access.');$active=(int)($_POST['is_active']??1);$s=$db->prepare('UPDATE users SET is_active=? WHERE email=?');$s->bind_param('is',$active,$email);$s->execute();admin_audit($db,'account_status','customer',$email,$active?'active':'disabled');redirect_with_message('customers.php','Customer access updated.');}
    if($action==='delete'){if(!admin_can('customers.delete'))redirect_with_message('customers.php','Only a super administrator can delete customers.');try{$db->begin_transaction();$user=$db->execute_query('SELECT profile_image FROM users WHERE email=? FOR UPDATE',[$email])->fetch_assoc();if(!$user)throw new RuntimeException('Customer not found.');$anonymous='deleted+'.substr(hash('sha256',strtolower($email)),0,20).'@invalid.local';$db->execute_query("UPDATE bookings SET user_email=?,customer_name='Deleted customer' WHERE user_email=?",[$anonymous,$email]);$db->execute_query('UPDATE offer_redemptions SET user_email=? WHERE user_email=?',[$anonymous,$email]);$db->execute_query('DELETE FROM family_members WHERE user_email=?',[$email]);$db->execute_query("DELETE r FROM notification_reads r JOIN notifications n ON n.id=r.notification_id WHERE r.user_email=? OR (n.audience='user' AND n.user_email=?)",[$email,$email]);$db->execute_query("DELETE FROM notifications WHERE audience='user' AND user_email=?",[$email]);$db->execute_query("UPDATE message SET email='deleted@invalid.local',fname='Deleted',lname='Customer' WHERE email=?",[$email]);$db->execute_query('DELETE FROM users WHERE email=?',[$email]);admin_audit($db,'anonymize_delete','customer',$anonymous,'Customer PII removed; financial history retained');$db->commit();admin_remove_unused_image($db,$user['profile_image']??null);redirect_with_message('customers.php','Customer account and personal data were removed. Financial booking history was anonymized and retained.');}catch(Throwable $error){try{$db->rollback();}catch(Throwable $ignored){}redirect_with_message('customers.php','Customer deletion could not be completed safely.');}}
}
$viewEmail=trim($_GET['view']??'');$viewCustomer=null;$customerBookings=[];
if($viewEmail!==''){$s=$db->prepare('SELECT name,email,address,phone,is_active,created_at FROM users WHERE email=?');$s->bind_param('s',$viewEmail);$s->execute();$viewCustomer=$s->get_result()->fetch_assoc();if($viewCustomer){$s=$db->prepare('SELECT b.*,p.name package_name,s.name state_name FROM bookings b LEFT JOIN packages p ON p.id=b.package_id LEFT JOIN states s ON s.id=p.state_id WHERE b.user_email=? ORDER BY b.created_at DESC');$s->bind_param('s',$viewEmail);$s->execute();$result=$s->get_result();while($row=$result->fetch_assoc())$customerBookings[]=$row;}}
$customers=$db->query('SELECT u.*,COUNT(b.id) booking_count,COALESCE(SUM(b.total_amount),0) booking_value FROM users u LEFT JOIN bookings b ON b.user_email=u.email GROUP BY u.email ORDER BY u.created_at DESC');$pageTitle='Customers';include '_header.php';?>
<div class="page-head"><div><span>Traveller records</span><h1>Customers</h1></div></div>
<?php if($viewCustomer):?><section class="panel customer-detail"><div class="panel-head"><h2><?php echo e($viewCustomer['name']);?> — Booked Packages</h2><a href="customers.php">Close</a></div><div class="customer-summary"><span><b>Email</b><?php echo e($viewCustomer['email']);?></span><span><b>Phone</b><?php echo e($viewCustomer['phone']?:'Not provided');?></span><span><b>Address</b><?php echo e($viewCustomer['address']?:'Not provided');?></span><span><b>Access</b><?php echo $viewCustomer['is_active']?'Enabled':'Disabled';?></span></div><div class="table-wrap"><table><thead><tr><th>Reference</th><th>Package</th><th>State / UT</th><th>Travel dates</th><th>Travellers</th><th>Total (INR)</th><th>Status</th></tr></thead><tbody><?php if(!$customerBookings):?><tr><td colspan="7">This customer has not booked a package.</td></tr><?php endif;?><?php foreach($customerBookings as $b):?><tr><td><?php echo e($b['booking_reference']?:'#'.$b['id']);?></td><td><?php echo e($b['package_name']?:$b['destination']);?></td><td><?php echo e($b['state_name']?:'-');?></td><td><?php echo e($b['from_date']);?><small>to <?php echo e($b['to_date']);?></small></td><td><?php echo (int)$b['people'];?></td><td><?php echo inr($b['total_amount']);?></td><td><span class="pill"><?php echo e($b['status']);?></span></td></tr><?php endforeach;?></tbody></table></div></section><?php endif;?>
<section class="panel"><div class="table-wrap"><table><thead><tr><th>Customer</th><th>Contact</th><th>Address</th><th>Bookings</th><th>Value (INR)</th><th>Access</th></tr></thead><tbody><?php while($u=$customers->fetch_assoc()):?><tr><td><a class="customer-link" href="customers.php?view=<?php echo urlencode($u['email']);?>"><strong><?php echo e($u['name']);?></strong><small>View booked packages</small></a></td><td><?php echo e($u['email']);?><small><?php echo e($u['phone']);?></small></td><td><?php echo e($u['address']);?></td><td><?php echo (int)$u['booking_count'];?></td><td><?php echo inr($u['booking_value']);?></td><td><div class="action-row"><form method="post"><?php echo csrf_input();?><input type="hidden" name="action" value="access"><input type="hidden" name="email" value="<?php echo e($u['email']);?>"><input type="hidden" name="is_active" value="<?php echo $u['is_active']?0:1;?>"><button class="<?php echo $u['is_active']?'danger':'primary-btn';?>"><?php echo $u['is_active']?'Disable':'Enable';?></button></form><form method="post" onsubmit="return confirm('Delete this customer account? Booking history will be retained.')"><?php echo csrf_input();?><input type="hidden" name="action" value="delete"><input type="hidden" name="email" value="<?php echo e($u['email']);?>"><button class="danger" title="Delete customer"><i class="fa-solid fa-trash"></i></button></form></div></td></tr><?php endwhile;?></tbody></table></div></section><?php include '_footer.php';?>
